let localExam=null,localExamIndex=0,localExamAnswers=[],localExamEnd=0,localExamTick=0;
const renderBeforeRegional=render;
render=function(){
 content.classList.toggle('regional-view',['exams','roadmap','localstudy'].includes(view));
 if(view==='exams')renderLocalExams();else if(view==='roadmap')renderRoadmap();else if(view==='localstudy')renderLocalStudy();else renderBeforeRegional();
};
function renderLocalExams(){clearInterval(localExamTick);if(localExam){renderLocalExamQuestion();return}content.innerHTML=`<span class="eyebrow">NGÂN HÀNG ÔN LUYỆN ĐỊA PHƯƠNG</span><h1>Đề thi theo vùng, làm trực tiếp có tính giờ</h1><p class="muted">Các bộ mô phỏng cấu trúc và yêu cầu cần đạt của chương trình GDPT; không gắn nhãn đề chính thức của Sở GD&ĐT.</p><div class="exam-grid">${localExams.map(e=>`<article class="panel exam-card"><span class="card-kicker">${e.province.toUpperCase()} · ${e.tag}</span><h2>${e.title}</h2><p>5 câu trắc nghiệm · ${e.minutes} phút · Có lời giải từng câu.</p><button class="primary" data-local-exam="${e.id}">Bắt đầu làm bài</button></article>`).join('')}</div><div class="notice">Muốn luyện nhiều câu hơn, mở “Ôn thi & Luyện đề” để AI tạo bộ 5–20 câu theo môn và khối.</div>`;document.querySelectorAll('[data-local-exam]').forEach(b=>b.onclick=()=>startLocalExam(b.dataset.localExam))}
function startLocalExam(id){localExam=localExams.find(e=>e.id===id);localExamIndex=0;localExamAnswers=[];localExamEnd=Date.now()+localExam.minutes*60000;renderLocalExamQuestion()}
function examClock(){const left=Math.max(0,Math.ceil((localExamEnd-Date.now())/1000)),m=Math.floor(left/60),s=left%60;const el=$('#examClock');if(el)el.textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;if(!left){clearInterval(localExamTick);finishLocalExam()}}
function renderLocalExamQuestion(){clearInterval(localExamTick);const q=localExam.questions[localExamIndex];content.innerHTML=`<div class="workspace"><div class="exam-status"><span>${localExam.province} · ${localExam.title}</span><strong id="examClock">00:00</strong></div><section class="panel"><div class="quiz-top"><span>Câu ${localExamIndex+1}/${localExam.questions.length}</span><span>${localExam.tag}</span></div><h2 class="exam-question">${q[0]}</h2><div class="answers">${q[1].map((a,i)=>`<button class="answer" data-local-answer="${i}">${String.fromCharCode(65+i)}. ${a}</button>`).join('')}</div><div id="localExplain" role="status"></div><button class="primary" id="localNext" hidden>${localExamIndex===localExam.questions.length-1?'Nộp bài':'Câu tiếp theo'}</button></section></div>`;document.querySelectorAll('[data-local-answer]').forEach(b=>b.onclick=()=>answerLocalExam(Number(b.dataset.localAnswer)));$('#localNext').onclick=()=>{localExamIndex++;if(localExamIndex>=localExam.questions.length)finishLocalExam();else renderLocalExamQuestion()};examClock();localExamTick=setInterval(examClock,1000)}
function answerLocalExam(i){if(localExamAnswers[localExamIndex]!=null)return;localExamAnswers[localExamIndex]=i;const q=localExam.questions[localExamIndex];document.querySelectorAll('[data-local-answer]').forEach((b,n)=>{b.disabled=true;b.classList.toggle('correct',n===q[2]);b.classList.toggle('wrong',n===i&&i!==q[2])});$('#localExplain').innerHTML=`<div class="notice"><b>${i===q[2]?'Chính xác!':'Chưa đúng.'}</b> ${q[3]}</div>`;$('#localNext').hidden=false}
function finishLocalExam(){clearInterval(localExamTick);const total=localExam.questions.length,score=localExam.questions.reduce((n,q,i)=>n+(localExamAnswers[i]===q[2]),0),pct=Math.round(score/total*100),done=localExam;featureState.points+=score*2;saveFeatures();upgradeState.attempts.unshift({subject:`Đề ${done.province}`,grade,date:new Date().toISOString(),score,total,pct});saveUpgrades();localExam=null;content.innerHTML=`<div class="workspace panel result-celebration"><div class="medal">${pct>=80?'🏆':'🌱'}</div><span class="eyebrow">ĐÃ NỘP BÀI</span><h1>${score}/${total} câu đúng · ${pct}%</h1><p class="muted">Kết quả đã được lưu vào Tiến độ của tôi.</p><div class="actions center"><button class="primary" data-go="exams">Chọn đề khác</button><button class="secondary" data-go="progress">Xem tiến độ</button></div></div>`;bindCommon()}
function renderRoadmap(){const saved=JSON.parse(localStorage.getItem('buddy-roadmap')||'null');content.innerHTML=`<span class="eyebrow">LỘ TRÌNH CÁ NHÂN HÓA</span><h1>Lập lịch ôn thi theo mục tiêu</h1><p class="muted">Nhập mục tiêu, Buddy chia thành việc nhỏ mỗi ngày và lưu riêng trên thiết bị.</p><div class="roadmap-layout"><section class="panel"><label>Môn học<select id="roadSubject">${practiceSubjects.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Mục tiêu điểm<input id="roadScore" type="number" min="5" max="10" step="0.5" value="8"></label><label>Ngày thi<input id="roadDate" type="date" min="${new Date().toISOString().slice(0,10)}"></label><label>Phút học mỗi ngày<input id="roadMinutes" type="number" min="20" max="180" value="45"></label><button class="primary wide" id="makeRoadmap">Tạo lộ trình và To-do</button></section><section class="panel" id="roadResult">${saved?roadmapHTML(saved):'<div class="empty-result"><span>◫</span><p>Lộ trình sẽ xuất hiện tại đây.</p></div>'}</section></div>`;$('#makeRoadmap').onclick=makeRoadmap}
function makeRoadmap(){const subject=$('#roadSubject').value,score=Number($('#roadScore').value),minutes=Number($('#roadMinutes').value),target=$('#roadDate').value;if(!target){toast('Hãy chọn ngày thi.');return}const days=Math.max(1,Math.min(60,Math.ceil((new Date(target)-new Date())/86400000))),phases=['Ôn lý thuyết trọng tâm','Luyện câu nền tảng','Luyện vận dụng','Làm đề và chữa lỗi'],plan=Array.from({length:Math.min(days,14)},(_,i)=>({day:i+1,task:`${phases[Math.min(3,Math.floor(i/Math.max(1,days/4)))]} · ${subject}`,minutes}));const data={subject,score,target,days,plan};localStorage.setItem('buddy-roadmap',JSON.stringify(data));plan.slice(0,7).forEach((p,i)=>{if(!featureState.todos.some(t=>t.title===p.task))featureState.todos.push({id:Date.now()+i,title:p.task,zone:i<2?'urgent-important':'important',done:false})});saveFeatures();$('#roadResult').innerHTML=roadmapHTML(data);toast('Đã tạo lộ trình và thêm 7 việc vào To-do.')}
function roadmapHTML(r){return `<div class="panel-head"><h2>${r.subject} · mục tiêu ${r.score} điểm</h2><span class="pill">Còn ${r.days} ngày</span></div><div class="road-list">${r.plan.map(p=>`<article><b>Ngày ${p.day}</b><span>${p.task}</span><small>${p.minutes} phút</small></article>`).join('')}</div><button class="secondary wide" data-go="focus">Mở Pomodoro & To-do</button>`}
function renderLocalStudy(){const rows=[['Địa lý','Cao nguyên đá Đồng Văn','Địa hình karst, di sản địa chất và cách con người thích nghi với môi trường núi đá.'],['Địa lý','Sông Nho Quế – hẻm Tu Sản','Mối liên hệ giữa địa hình, dòng chảy, du lịch và bảo vệ cảnh quan.'],['Lịch sử','Dấu tích và ký ức vùng biên','Tìm hiểu lịch sử địa phương bằng tư liệu, hiện vật và lời kể có kiểm chứng.'],['Văn hóa','Chợ phiên vùng cao','Không gian trao đổi sản vật, gặp gỡ cộng đồng và gìn giữ bản sắc.'],['Văn hóa','Dân ca và nghề thủ công','Tiếp cận di sản với thái độ tôn trọng chủ thể văn hóa và quyền cộng đồng.'],['Công dân','Du lịch có trách nhiệm','Xin phép trước khi chụp ảnh, không xả rác và tôn trọng không gian thiêng.']];content.innerHTML=`<span class="eyebrow">GIÁO DỤC ĐỊA PHƯƠNG HÀ GIANG</span><h1>Lịch sử, địa lý và văn hóa quê hương</h1><p class="muted">Chuyên đề tra cứu nhanh dành cho môn tích hợp và hoạt động trải nghiệm.</p><div class="local-topic-grid">${rows.map((r,i)=>`<article class="panel local-topic"><span>0${i+1}</span><small>${r[0].toUpperCase()}</small><h2>${r[1]}</h2><p>${r[2]}</p><button class="secondary" data-local-practice>Ôn bằng câu hỏi</button></article>`).join('')}</div><div class="notice">Nội dung là bản tóm tắt học tập. Khi làm bài nghiên cứu, hãy đối chiếu tài liệu giáo dục địa phương do nhà trường cung cấp và nguồn của cơ quan văn hóa.</div>`;document.querySelectorAll('[data-local-practice]').forEach(b=>b.onclick=()=>{localExam=null;navigate('exams')})}

